(* [comment removed for export] *)
Lemma stk_of_defined (M : word -> option byte) b : 0 <= b -> forall n : nat, b + 24 * Z.of_nat n <= 2 ^ 64 -> L5.defined M b (24 * Z.of_nat n) ->
  exists stk, length stk = n /\ forall i, (i < n)%nat -> PQMA.mstate_at RSEGS M (b + 24 * Z.of_nat i) (nth i stk PQMA.ms_root).
Proof.
