Lemma chk1 fx R M cur k :
  getr R (reg 9) = Z_to_bv 64 cur -> getr R (reg 22) = Z_to_bv 64 SBL -> 0 <= cur < 2 ^ 47 ->
  rdn RSEGS M (Z_to_bv 64 (cur / 8 + SBL)) 1%nat = Some [Z_to_bv 8 k] ->
  (k = 0 \/ (1 <= k <= 7 /\ cur mod 8 < k)) ->
  exists R', msteps RSEGS (mst fx R 0xc40c0 M) (mst fx R' 0xc40d0 M)
