(* [comment removed for export] *)
Definition rqe (Ri : bvmap 5 word) : Prop := getr Ri (reg 2) = Z_to_bv 64 (sp - 96) /\ getr Ri (reg 8) = Z_to_bv 64 ov /\ getr Ri (reg 22) = Z_to_bv 64 SBL /\ csl Ri.
Definition RQE : list nat := (2 :: 8 :: 22 :: CSL)%nat.
Lemma rqe_piece (KS : list nat) Ra Rb : (forall x, In x KS -> getr Rb (reg x) = getr Ra (reg x)) -> forallb (fun k0 => existsb (Nat.eqb k0) KS) RQE = true ->
