(* [comment removed for export] *)
Lemma ext8_tail (fxq : FPState) Rq Mq mdq LKq Awq crq kq :
  CINV Mq mdq LKq Awq crq kq 1 1 -> rq Rq -> n <= 255 -> getr Rq (reg 20) = Z_to_bv 64 n -> getr Rq (reg 21) = Z_to_bv 64 (ov + 8) -> getr Rq (reg 24) = Z_to_bv 64 ((ov + 8) / 8 + SBL) ->
