Section WithHeap.
Context {SCFG_P : ScfgP}.
Variable AQ : pq_addrs.
Variables (L : asan_layout) (ar : asan_run) (C : asan_statics_cells) (HI : asan_iface) (P : NESKA.sink_policyA).
Hypothesis LY : PMA.layout L C.
Hypothesis HIok : HAJ.asan_iface_okR L ar C SCFG HI.
Hypothesis PO : NESKA.sink_policyA_ok L P.
Hypothesis HBS : NESKA.spa_hb P NESK.SMZ.
Let LYa := PMA.ly_as0 L C LY.
(* [comment removed for export] *)
Hypothesis PB : NESKA.push_back_specA RSEGS AD EE L ar HI P.
Hypothesis NTB16 : NECSA.ntb_specA RSEGS AD L ar HI P 2 (ne_ntb_u16 EE).
Hypothesis NTB32 : NECSA.ntb_specA RSEGS AD L ar HI P 4 (ne_ntb_u32 EE).

Abbreviation enc_atA := (NEMA.enc_atA RSEGS EE L ar).
Abbreviation sink_atA := (NESKA.sink_atA RSEGS L ar P).
