Definition rq (Ri : bvmap 5 word) : Prop :=
  getr Ri (reg 2) = Z_to_bv 64 (sp - 80) /\ getr Ri (reg 8) = Z_to_bv 64 ov /\ getr Ri (reg 9) = Z_to_bv 64 (ov + 8) /\ getr Ri (reg 18) = Z_to_bv 64 p
  /\ getr Ri (reg 19) = Z_to_bv 64 (p + 8) /\ getr Ri (reg 20) = Z_to_bv 64 n /\ getr Ri (reg 21) = Z_to_bv 64 SBL /\ getr Ri (reg 22) = Z_to_bv 64 ((p + 8) / 8 + SBL) /\ csl Ri.
