(* [comment removed for export] *)
Definition rql (Ri : bvmap 5 word) : Prop :=
  getr Ri (reg 2) = Z_to_bv 64 (sp - 80) /\ getr Ri (reg 8) = Z_to_bv 64 ov /\ getr Ri (reg 9) = Z_to_bv 64 (ov + 8) /\ getr Ri (reg 20) = Z_to_bv 64 ((ov + 8) / 8 + SBL)
  /\ getr Ri (reg 21) = Z_to_bv 64 SBL /\ csl Ri.
Definition RQLL : list nat := (2 :: 8 :: 9 :: 20 :: 21 :: CSL)%nat.
Lemma rql_call Ra Rb : regs_preserved Ra Rb -> rql Ra -> rql Rb.
