(* [comment removed for export] *)
Local Ltac midV Rq :=
  constr:(fun j : nat => match j with 2%nat => sp | 10%nat => ov | 11%nat => p | 33%nat => d | 34%nat => n | 35%nat => p + 8 | 36%nat => ov + 8 | 41%nat => osk | 44%nat => r
     | 45%nat => bv_unsigned (getr R (reg 8)) | 46%nat => bv_unsigned (getr R (reg 9)) | 47%nat => bv_unsigned (getr R (reg 18)) | 48%nat => bv_unsigned (getr R (reg 19))
     | 49%nat => bv_unsigned (getr R (reg 20)) | 50%nat => bv_unsigned (getr R (reg 21)) | 51%nat => bv_unsigned (getr R (reg 22)) | 52%nat => bv_unsigned (getr R (reg 23))
     | 55%nat => bv_unsigned (getr Rq (reg 10)) | 56%nat => bv_unsigned (getr Rq (reg 11)) | 57%nat => bv_unsigned (getr Rq (reg 12)) | _ => 0 end).
Local Ltac loopV Rq c b jj :=
  constr:(fun j : nat => match j with 2%nat => sp | 10%nat => ov | 36%nat => ov + 8 | 37%nat => b | 38%nat => jj | 39%nat => c | 41%nat => osk | 44%nat => r
     | 45%nat => bv_unsigned (getr R (reg 8)) | 46%nat => bv_unsigned (getr R (reg 9)) | 47%nat => bv_unsigned (getr R (reg 18)) | 48%nat => bv_unsigned (getr R (reg 19))
     | 49%nat => bv_unsigned (getr R (reg 20)) | 50%nat => bv_unsigned (getr R (reg 21)) | 51%nat => bv_unsigned (getr R (reg 22)) | 52%nat => bv_unsigned (getr R (reg 23))
     | 55%nat => bv_unsigned (getr Rq (reg 10)) | 56%nat => bv_unsigned (getr Rq (reg 11)) | 57%nat => bv_unsigned (getr Rq (reg 12)) | _ => 0 end).
Local Ltac evV Rq eb ed cn :=
  constr:(fun j : nat => match j with 2%nat => sp | 10%nat => ov | 38%nat => eb | 39%nat => ed | 41%nat => osk | 42%nat => cn | 44%nat => r
     | 45%nat => bv_unsigned (getr R (reg 8)) | 46%nat => bv_unsigned (getr R (reg 9)) | 47%nat => bv_unsigned (getr R (reg 18)) | 48%nat => bv_unsigned (getr R (reg 19))
     | 49%nat => bv_unsigned (getr R (reg 20)) | 50%nat => bv_unsigned (getr R (reg 21)) | 51%nat => bv_unsigned (getr R (reg 22)) | 52%nat => bv_unsigned (getr R (reg 23))
     | 55%nat => bv_unsigned (getr Rq (reg 10)) | 56%nat => bv_unsigned (getr Rq (reg 11)) | 57%nat => bv_unsigned (getr Rq (reg 12)) | _ => 0 end).
Local Ltac feedP P := L5SAR.feed P ltac:(first [assumption | unfold PNAENBTP.aligned; assumption | unfold PNAENBTP.aligned; apply al8_add8; assumption | apply wid | apply wrng | L5SAR.greg | L5SAR.gmem | lia]).

(* [comment removed for export] *)
Local Ltac pstep INV :=
  pose proof (Kvis cells _ _ _ _ _ _ _ _ INV COK) as VIS; cbv beta in VIS;
  destruct VIS as (IC0 & CSB & CUAR & SPR & _ & SWR & SDF & OV1 & OV2 & OV8 & OBIG & ZOV & OWR & Z8 & Z24 & Z32 & _ & OQ & OK1 & OK2 & OK8 & EV24 & EV32 & _ & EB & _ & EDEP & _ & _ & CELLS & _);
  pose proof (Forall_inv CELLS) as Y8; pose proof (Forall_inv (Forall_inv_tail CELLS)) as Y16; pose proof (Forall_inv (Forall_inv_tail (Forall_inv_tail CELLS))) as Y24;
  pose proof (Forall_inv (Forall_inv_tail (Forall_inv_tail (Forall_inv_tail CELLS)))) as Y32;
  pose proof (Forall_inv (Forall_inv_tail (Forall_inv_tail (Forall_inv_tail (Forall_inv_tail CELLS))))) as Y40;
  pose proof (Forall_inv (Forall_inv_tail (Forall_inv_tail (Forall_inv_tail (Forall_inv_tail (Forall_inv_tail CELLS)))))) as Y48;
  pose proof (Forall_inv (Forall_inv_tail (Forall_inv_tail (Forall_inv_tail (Forall_inv_tail (Forall_inv_tail (Forall_inv_tail CELLS))))))) as Y56;
  pose proof (Forall_inv (Forall_inv_tail (Forall_inv_tail (Forall_inv_tail (Forall_inv_tail (Forall_inv_tail (Forall_inv_tail (Forall_inv_tail CELLS)))))))) as Y64;
  pose proof (Forall_inv (Forall_inv_tail (Forall_inv_tail (Forall_inv_tail (Forall_inv_tail (Forall_inv_tail (Forall_inv_tail (Forall_inv_tail (Forall_inv_tail CELLS))))))))) as Y72;
  cbn [fst snd] in Y8, Y16, Y24, Y32, Y40, Y48, Y56, Y64, Y72; clear CELLS;
  pose proof (view_at cells _ _ _ _ _ _ _ _ INV) as VW; cbv beta in VW; destruct VW as (VP0 & VP8 & ZP0 & ZP8 & DEFq & ACCq & BSq & VISd).

(* [comment removed for export] *)
Lemma FIN (fx7 : FPState) R7 M7 md7 LKq Awq crq kq lo hi :
  CINV M7 md7 LKq Awq crq kq lo hi -> 0 <= lo -> hi <= n + 6 -> regs_preserved R R7 ->
